import{j as e}from"./blog-pages-BaE92hYU.js";import{P as i}from"./compare-pages-BwwJjgUS.js";const r=[{factor:"Pengerang asset profile",atlantis:"Pengerang Integrated Complex (PIC) in Johor, Malaysia: Petronas RAPID refinery (~300,000 bpd) + integrated petrochemical complex + LNG / regasification (Pengerang LNG Sdn Bhd, jointly owned with PETCO Trading)",competitor:"—"},{factor:"LNG / regas asset count",atlantis:"Pengerang LNG: 2 full-containment 200,000 m&sup3; LNG storage tanks, regasification capacity ~3.5 MTPA, breakwater + jetty + ORV/SCV regasifiers",competitor:"—"},{factor:"Damage mechanism stack",atlantis:"Brittle fracture at -162&deg;C, 9% Ni weld defects, ORV/SCV regasifier seawater corrosion, breakwater concrete + steel piling, equatorial humidity-driven external CUI, jetty marine corrosion (Johor Straits)",competitor:"—"},{factor:"Regulatory regime",atlantis:"DOSH (Department of Occupational Safety and Health Malaysia), Suruhanjaya Tenaga (Energy Commission Malaysia) for gas regulation, Petronas internal standards (PTS) often more stringent than international baseline, API 625 / EN 14620 / NFPA 59A cryogenic codes",competitor:"—"},{factor:"ROI typical (Pengerang LNG)",atlantis:"$2.5M&ndash;$6M/yr &mdash; driven by integrated refinery + petrochemical + LNG coexistence in one digital twin, plus regulatory audit-pack automation",competitor:"—"},{factor:"Implementation",atlantis:"12&ndash;18 weeks first tank + first regasifier; 4&ndash;6 weeks per subsequent asset. Coexistence with Petronas PTS-compliant SAP / IFS / PI landscape.",competitor:"—"}],t=[{question:"What makes Pengerang Integrated Complex (PIC) a distinctive digital twin candidate?",answer:"Pengerang is one of the most integrated brownfield-to-greenfield petrochemical clusters built in the last decade. The Petronas RAPID (Refinery and Petrochemical Integrated Development) project at Pengerang in Johor includes a ~300,000 bpd refinery (commissioned 2019), a multi-billion-dollar petrochemical complex (PChem, in partnership with Saudi Aramco via Saudi Aramco&rsquo;s 50% stake), the Pengerang LNG regasification terminal (jointly owned by Petronas Gas Berhad and PETCO Trading), the Pengerang Deepwater Petroleum Terminal (jetty + storage), and supporting utilities. The digital twin opportunity is the integrated nature: one platform handling cryogenic LNG, ambient sour service in the refinery, polymer-grade petrochemical service, and marine jetty operations from a single 3D model. Few sites in the world combine this breadth in one location."},{question:"How does Pengerang LNG regasification differ from an export terminal?",answer:"Pengerang LNG is a regasification (import) terminal, not an export liquefaction facility &mdash; the workflow differs in important ways. Inbound LNG cargoes from various sources (QatarEnergy, US Gulf exporters, Russian sources historically, Australian Northwest Shelf, etc.) discharge to the 2 full-containment 200,000 m&sup3; storage tanks via the unloading jetty. Regasification through Open Rack Vaporisers (ORV) using seawater as the heat source, or Submerged Combustion Vaporisers (SCV) for backup, sends ~3.5 MTPA into the Peninsular Malaysia gas pipeline grid. Damage mechanisms shift accordingly: ORV seawater-side corrosion is a significant integrity concern not present in export terminals, while the BOG management workload is lighter than at an export facility. Atlantis ships ORV / SCV inspection templates as part of the regas asset library."},{question:"How does Atlantis integrate with Petronas&rsquo;s PTS (Petronas Technical Standards) regime?",answer:"PTS standards are Petronas&rsquo;s in-house technical specifications, often more stringent than international API/ASME/EN baselines. Petronas requires PTS compliance across all owned and operated assets, with audit-pack evidence to PTS detail. Atlantis ships the PTS audit-pack template alongside the API 510/570/625 + EN 13445/14620 templates, with field-level mapping between equivalent codes built in. Integration with Petronas&rsquo;s SAP PM landscape (PAM, the Petronas Asset Management system), IFS Applications (legacy in some business units), and AVEVA PI is standard via BAPI / REST / OPC-UA connectors. Petronas inspection contractors (Penyelidikan dan Pengujian Bahan Sdn Bhd, Bureau Veritas Malaysia, ABS, DNV, Lloyd&rsquo;s, Mistras Malaysia, IRClass) integrate via the Atlantis REST API."},{question:"What about the equatorial humidity impact on CUI?",answer:"Johor sits at 1.5&deg;N latitude with year-round high humidity (85&ndash;95% RH typical) and no dry season, making CUI rates noticeably higher than the temperate-climate refinery average. Atlantis ships API 583 CUI risk overlays directly on the 3D twin, with equatorial-climate-aware CUI inspection scheduling that defaults to more aggressive re-inspection intervals than US Gulf Coast or European refineries. The integrated nature of PIC &mdash; refinery + petrochemical + LNG storage in one cluster &mdash; means CUI tracking spans the full asset mix from one platform."},{question:"How does the Pengerang Deepwater Petroleum Terminal jetty integrate?",answer:"The Pengerang Deepwater Petroleum Terminal includes one of the deepest-draft LNG and crude oil jetties in Southeast Asia, handling Q-Max and Q-Flex LNG carriers as well as VLCC-scale crude. Marine jetty integrity is a first-class workflow in Atlantis: jetty pile UT thickness grids (annual cadence due to severe Johor Straits marine corrosion), loading arm condition monitoring, quick-connect/disconnect coupling inspection, fender system condition, and breakwater integrity. The 3D twin overlays splash-zone external corrosion bands on the jetty pile model, with remaining-life trends visible to the integrity engineer."}];function l(){const n={"@context":"https://schema.org","@graph":[{"@type":"Article",headline:"Digital Twin for Petronas RAPID Pengerang LNG: Integrated Complex Integrity [2026]",datePublished:"2026-05-25",dateModified:"2026-05-25",author:{"@type":"Person",name:"Anoop Rayavarapu"},publisher:{"@type":"Organization",name:"Atlantis NDT"},mainEntityOfPage:{"@type":"WebPage","@id":"https://atlantisndt.com/digital-twins/lng-terminal-pengerang"}},{"@type":"FAQPage",mainEntity:t.map(a=>({"@type":"Question",name:a.question,acceptedAnswer:{"@type":"Answer",text:a.answer}}))}]};return e.jsx(i,{title:"Digital Twin for Petronas RAPID Pengerang LNG Terminal [2026]",description:"Petronas RAPID Pengerang digital twin: integrated refinery + petrochemical + LNG regasification, 9% Ni weld inspection, ORV seawater corrosion, Johor jetty integrity. PTS-compliant audit packs.",canonical:"https://atlantisndt.com/digital-twins/lng-terminal-pengerang",eyebrow:"Use Case · Location",h1:"Atlantis Digital Twin for Pengerang LNG: PIC Integrated Cryogenic + Refinery + Petrochemical [2026]",intro:"The Pengerang Integrated Complex (PIC) in Johor combines Petronas’s RAPID 300,000 bpd refinery, the Saudi Aramco JV petrochemical complex, the 3.5 MTPA Pengerang LNG regasification terminal, and the deepwater jetty in one cluster. Atlantis Digital Twin handles 9% Ni weld inspection, API 625 tank integrity, ORV seawater corrosion, and Johor Straits marine jetty integrity in a PTS-compliant audit pack workflow.",heroGradient:"from-emerald-700 to-cyan-900",competitorLabel:"Pengerang Specifics",compareRows:r,faqs:t,related:[{href:"/digital-twins/lng-terminal",title:"LNG Terminal Use Case",blurb:"Asset-class deep-dive."},{href:"/digital-twin-pengerang",title:"Pengerang (Location)",blurb:"Full Pengerang DT coverage page."},{href:"/digital-twin-malaysia",title:"Malaysia Country Coverage",blurb:"Pan-Malaysia DT programmes."},{href:"/digital-twins/refinery",title:"Refinery Use Case",blurb:"Adjacent &mdash; RAPID refinery integrity."},{href:"/contact",title:"Book a Pengerang Demo",blurb:"Bring one regasifier&rsquo;s inspection record. 30-minute demo."}],ctaTitle:"See Pengerang LNG as a Live Integrated Twin",ctaSubtitle:"Bring one ORV regasifier’s inspection record and one tank’s 9% Ni weld map. We’ll have it running as an Atlantis twin in a 30-minute demo.",structuredData:n,bodyChildren:e.jsxs(e.Fragment,{children:[e.jsx("h2",{children:"Why Pengerang Integrated Complex is a distinctive digital twin opportunity"}),e.jsx("p",{children:"The Pengerang Integrated Complex (PIC) sits on the southeastern tip of Peninsular Malaysia in Johor, opposite Singapore across the Johor Straits. Within a single industrial footprint, PIC combines: Petronas RAPID (Refinery and Petrochemical Integrated Development), a ~300,000 bpd refinery commissioned in 2019; a Petronas Chemicals + Saudi Aramco JV petrochemical complex producing olefins, polymers, and specialty chemicals; Pengerang LNG Sdn Bhd, a regasification terminal with 2 full-containment 200,000 m³ LNG storage tanks and ~3.5 MTPA send-out capacity into the Peninsular Malaysia gas pipeline grid; and the Pengerang Deepwater Petroleum Terminal handling LNG carriers, crude tankers, and product cargoes. Few sites in the world combine cryogenic, ambient-sour, polymer-grade, and marine-jetty integrity in a single integrated cluster."}),e.jsx("h2",{children:"The Pengerang damage-mechanism stack"}),e.jsxs("ul",{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Brittle fracture at -162°C."})," 9% Ni inner tank shells and cryogenic piping require brittle-fracture screening per ASME Section VIII Div. 2 Part 3 and API 579 Part 3."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"9% Ni weld defects."})," Inspected per API 625 / EN 14620 / BS 7777 with PAUT, RT, and MT/PT. Each weld registered with heat numbers, welder ID, WPS reference, and full NDE record."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"ORV / SCV regasifier seawater corrosion."})," Open Rack Vaporisers use seawater as the heat source for LNG regasification. Seawater-side corrosion on the aluminium-alloy heat-transfer surface is a primary ORV degradation mechanism. Submerged Combustion Vaporisers (SCV) backup units have their own fouling and corrosion concerns. Atlantis ships ORV / SCV inspection templates."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Equatorial humidity-driven CUI."})," Johor’s 1.5°N latitude means year-round high humidity (85–95% RH) and no dry season, driving CUI rates higher than temperate-climate norms."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Johor Straits jetty marine corrosion."})," Severe marine environment with high salinity and tropical temperatures. Jetty splash-zone external corrosion on piles, loading arms, and quick-connect couplings tracked via annual UT thickness grids."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Refinery-side damage mechanisms."})," The adjacent RAPID refinery brings the full API 571 mechanism set: sour service, HTHA, CUI, naphthenic acid, sulfidation. The integrated digital twin handles refinery + LNG + petrochemical from one platform."]})]}),e.jsx("h2",{children:"The integrated workflow advantage"}),e.jsx("p",{children:"PIC’s integrated nature is the digital twin opportunity. A single Atlantis deployment covers the LNG regas terminal (2 tanks, 4 ORV regasifiers, 2 SCV backup units, BOG system, send-out metering), the adjacent RAPID refinery (8–12 process units, 30,000–100,000 CMLs), the petrochemical complex (steam crackers, polymerisation units, derivatives), and the deepwater jetty (LNG + crude + product berths). One 3D twin, one inspection workflow, one FFS/RBI engine, one audit-pack generator covering API 510/570/625 + EN 13445/14620 + Petronas PTS. The integrated nature reduces total platform cost vs deploying separate tools for LNG, refinery, and petrochemical asset classes."}),e.jsx("h2",{children:"ORV / SCV regasification inspection workflow"}),e.jsx("p",{children:"Open Rack Vaporisers are the workhorse of LNG regasification — aluminium-alloy heat-transfer panels with LNG flowing through tubes and seawater cascading over the external panel surface. Seawater-side corrosion of the aluminium alloy is the primary degradation mechanism, driven by tropical seawater chemistry (salinity, dissolved oxygen, biofouling). Atlantis treats each ORV panel as a discrete asset record with annual external visual surveys, periodic UT thickness on the panel surface, and biofouling assessment. Submerged Combustion Vaporiser backup units have their own degradation profile (combustion-side corrosion, water-bath chemistry, burner integrity) that Atlantis tracks separately. Both classes feed into the API 579 FFS engine for fitness-for-service evaluation when degradation rates accelerate."}),e.jsx("h2",{children:"Petronas PTS audit-pack workflow"}),e.jsx("p",{children:"Petronas requires PTS (Petronas Technical Standards) compliance across all owned and operated assets, with detailed audit-pack evidence. PTS standards are often more stringent than international API/ASME/EN baselines — for example, PTS 60.2222 (in-service inspection of pressure vessels) requires more frequent CML re-inspection than API 510 for certain damage mechanisms. Atlantis ships the PTS audit-pack template alongside the API 510/570/625 + EN 13445/14620 templates, with field-level mapping between equivalent codes. PTS audit packs generate from the twin in <30 seconds, ready for Petronas internal audit, DOSH (Department of Occupational Safety and Health Malaysia) inspection, or Suruhanjaya Tenaga (Energy Commission) review."}),e.jsx("h2",{children:"ROI math for a Pengerang LNG + integrated deployment"}),e.jsx("p",{children:"For the Pengerang LNG terminal alone (~$2.5M–$6M/yr) plus integrated deployment across RAPID refinery and the petrochemical complex (additional value), Atlantis Digital Twin enterprise tier ($200K/yr) pays back through:"}),e.jsxs("ul",{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Tank out-of-service inspection deferral:"})," 2–4 year extension on 10-year cycle × $4M–$10M per inspection on each 200,000 m³ tank."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"ORV / SCV inspection efficiency:"})," Annual ORV external surveys + biofouling assessment streamlined via digital workflow = $200K–$500K/yr labour saved."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"RAPID refinery turnaround scope reduction:"})," 15–25% on integrated turnaround scope = additional $1M–$3M/yr averaged."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"PTS audit-pack automation:"})," 200–500 hours per year saved in audit-pack preparation across the integrated PIC complex."]})]}),e.jsx("h2",{children:"Implementation path for the Petronas PIC ecosystem"}),e.jsx("p",{children:"First tank + first ORV regasifier live in 12–18 weeks. Subsequent assets 4–6 weeks each. Integration with Petronas’s SAP PM (PAM module), AVEVA PI historian, and Maximo asset master is standard. Petronas inspection contractor pool integrating with Atlantis includes Penyelidikan dan Pengujian Bahan Sdn Bhd (PPB), Bureau Veritas Malaysia, ABS, DNV, Lloyd’s, Mistras Malaysia, IRClass, and the in-house Petronas inspection department. A full PIC deployment (LNG + RAPID refinery + petrochemical) typically lands in 12–18 months from kickoff to last-asset-live."})]})})}export{l as default};
